  const DETAILED_SOLUTIONS = {"1":{"title":"સમીકરણ પદ્ધતિ","steps":["હાલની ઉંમર x વર્ષ માનો. પ્રશ્નમાં 20 વર્ષ પછીની ઉંમરની સરખામણી 2 વર્ષ પહેલાંની ઉંમરના બમણા સાથે છે.","20 વર્ષ પછી ઉંમર = x + 20.","2 વર્ષ પહેલાં ઉંમર = x − 2; તેનો બમણો = 2(x − 2).","બંને સરખાં હોવાથી x + 20 = 2(x − 2).","કૌંસ ખોલો: x + 20 = 2x − 4. તેથી 24 = x.","અત્યારે અનુપની ઉંમર 24 વર્ષ છે."],"formula":"x+20 = 2(x−2)  →  x+20 = 2x−4  →  x = 24","check":"ચકાસણી: 2 વર્ષ પહેલાં 22 વર્ષ; તેનો બમણો 44. 20 વર્ષ પછી 44 વર્ષ. બંને બાજુ સરખી છે.","kind":"equation"},"2":{"title":"સમીકરણ પદ્ધતિ","steps":["પ્રિયાની હાલની ઉંમર x વર્ષ માનો.","12 વર્ષ પછી તેની ઉંમર x + 12 થશે.","4 વર્ષ પહેલાં તેની ઉંમર x − 4 હતી; પ્રશ્ન મુજબ 12 વર્ષ પછીની ઉંમર તેના ત્રણ ગણા જેટલી છે.","સમીકરણ: x + 12 = 3(x − 4).","કૌંસ ખોલતાં x + 12 = 3x − 12.","24 = 2x, એટલે x = 12 વર્ષ."],"formula":"x+12 = 3(x−4)  →  x+12 = 3x−12  →  x = 12","check":"ચકાસણી: હાલ 12; 12 વર્ષ પછી 24. ચાર વર્ષ પહેલાં 8; 8નો ત્રણ ગણો 24.","kind":"equation"},"3":{"title":"સમીકરણ પદ્ધતિ","steps":["ભૂપેનની હાલની ઉંમર x વર્ષ માનો.","14 વર્ષ પછી ઉંમર x + 14 થશે.","7 વર્ષ પહેલાં ઉંમર x − 7 હતી.","પ્રશ્નમાં 14 વર્ષ પછીની ઉંમર, 7 વર્ષ પહેલાંની ઉંમરના બમણા જેટલી છે: x + 14 = 2(x − 7).","કૌંસ ખોલો: x + 14 = 2x − 14.","28 = x. એટલે હાલની ઉંમર 28 વર્ષ."],"formula":"x+14 = 2(x−7)  →  x+14 = 2x−14  →  x = 28","check":"ચકાસણી: 7 વર્ષ પહેલાં 21; બમણું 42. 14 વર્ષ પછી 42.","kind":"equation"},"4":{"title":"ભૂતકાળની ઉંમરથી હાલની ઉંમર","steps":["લીલીની હાલની ઉંમર 12 વર્ષ છે.","ચાર વર્ષ પહેલાં લીલી 12 − 4 = 8 વર્ષની હતી.","એ જ સમયે રશેલ લીલીથી ત્રણ ગણી હતી, એટલે રશેલની તે સમયની ઉંમર 8 × 3 = 24 વર્ષ.","રશેલની હાલની ઉંમર મેળવવા પાછલા સમયથી 4 વર્ષ ઉમેરો: 24 + 4 = 28.","અહીં બંને ઉંમર માટે એક જ સમયબિંદુ (ચાર વર્ષ પહેલાં) રાખ્યું છે."],"formula":"લીલી: 12 → 4 વર્ષ પહેલાં 8  |  રશેલ: 8×3 = 24 → હાલ 24+4 = 28","check":"ચકાસણી: ચાર વર્ષ પહેલાં રશેલ 24 અને લીલી 8; 24 = 3×8.","kind":"timeline"},"5":{"title":"ભૂતકાળની ઉંમરથી હાલની ઉંમર","steps":["એલેક્સની હાલની ઉંમર 15 વર્ષ છે.","ત્રણ વર્ષ પહેલાં એલેક્સ 15 − 3 = 12 વર્ષનો હતો.","તે સમયે કેવિન એલેક્સ કરતાં બમણી ઉંમરનો હતો: 12 × 2 = 24 વર્ષ.","કેવિનની હાલની ઉંમર માટે ત્રણ વર્ષ ઉમેરો: 24 + 3 = 27 વર્ષ.","ભૂતકાળની સરખામણી કર્યા પછી હાલના સમય સુધી બંનેની ઉંમરમાં 3 વર્ષ ઉમેરાય છે."],"formula":"એલેક્સ: 15−3 = 12  |  કેવિન (તે સમયે): 2×12 = 24  |  હાલ: 24+3 = 27","check":"ચકાસણી: ત્રણ વર્ષ પહેલાં 24 અને 12; કેવિન બમણી ઉંમરનો હતો.","kind":"timeline"},"6":{"title":"ભૂતકાળની ઉંમરથી હાલની ઉંમર","steps":["માઇકની હાલની ઉંમર 10 વર્ષ છે.","પાંચ વર્ષ પહેલાં માઇક 10 − 5 = 5 વર્ષનો હતો.","તે સમયે જહોન માઇક કરતાં ત્રણ ગણો હતો: 5 × 3 = 15 વર્ષ.","જહોનની હાલની ઉંમર = 15 + 5 = 20 વર્ષ.","પહેલાંની ઉંમર કાઢતી વખતે 5 ઘટાડ્યા અને હાલની ઉંમર મેળવતી વખતે 5 ઉમેર્યા."],"formula":"માઇક: 10−5 = 5  |  જહોન: 3×5 = 15  |  હાલ: 15+5 = 20","check":"ચકાસણી: પાંચ વર્ષ પહેલાં જહોન 15 અને માઇક 5; 15 = 3×5.","kind":"timeline"},"7":{"title":"ભૂતકાળની ઉંમરથી હાલની ઉંમર","steps":["કેરોલની હાલની ઉંમર 15 વર્ષ છે.","10 વર્ષ પહેલાં કેરોલ 15 − 10 = 5 વર્ષની હતી.","તે સમયે એલિસ કેરોલ કરતાં ચાર ગણી હતી: 5 × 4 = 20 વર્ષ.","હાલની એલિસની ઉંમર = 20 + 10 = 30 વર્ષ.","આ પ્રશ્નમાં 10 વર્ષ પહેલાંની સરખામણી છે, તેથી બંને ઉંમરોને પહેલાં એ જ સમય સુધી લઈ જવું જરૂરી છે."],"formula":"કેરોલ: 15−10 = 5  |  એલિસ: 4×5 = 20  |  હાલ: 20+10 = 30","check":"ચકાસણી: 10 વર્ષ પહેલાં એલિસ 20 અને કેરોલ 5; 20 = 4×5.","kind":"timeline"},"8":{"title":"સરવાળો અને ગુણોત્તર","steps":["બે વર્ષ પહેલાં બંને ભાઈઓની કુલ ઉંમર 20 વર્ષ હતી.","બે વર્ષમાં દરેક ભાઈની ઉંમર 2 વર્ષ વધે છે; એટલે બંનેનો કુલ સરવાળો 2+2 = 4 વર્ષ વધે છે.","હાલનો કુલ સરવાળો = 20 + 4 = 24 વર્ષ.","હાલનો ગુણોત્તર મોટો:નાનો = 3:1 છે. કુલ ભાગ = 3+1 = 4.","એક ભાગ = 24 ÷ 4 = 6 વર્ષ. મોટો ભાઈ 3 ભાગ = 3×6 = 18 વર્ષ."],"formula":"2 વર્ષ પહેલાં કુલ 20  →  હાલ કુલ 24  →  3:1 એટલે 4 ભાગ  →  મોટો = 18","check":"ચકાસણી: ઉંમરો 18 અને 6; કુલ 24 અને ગુણોત્તર 18:6 = 3:1.","kind":"ratio"},"9":{"title":"સરવાળો અને ગુણોત્તર","steps":["પુત્રની ઉંમર 1 ભાગ અને પિતાની ઉંમર 2 ભાગ માનો, કારણ કે પિતા બમણી ઉંમરના છે.","કુલ ભાગ = 2+1 = 3.","ત્રણ ભાગનો સરવાળો 60 વર્ષ છે, એટલે એક ભાગ = 60 ÷ 3 = 20 વર્ષ.","પુત્રની ઉંમર એક ભાગ છે; તેથી પુત્ર 20 વર્ષનો છે."],"formula":"પિતા : પુત્ર = 2 : 1  |  કુલ 3 ભાગ = 60  |  1 ભાગ = 20","check":"ચકાસણી: પિતા 40 અને પુત્ર 20; સરવાળો 60 અને પિતા બમણા.","kind":"ratio"},"10":{"title":"સરવાળો અને ગુણોત્તર","steps":["મિત્રની ઉંમર 1 ભાગ માનો. વ્યક્તિની ઉંમર તેના ચાર ગણા હોવાથી 4 ભાગ થશે.","કુલ ભાગ = 4+1 = 5.","પાંચ ભાગ = 50 વર્ષ, એટલે એક ભાગ = 50 ÷ 5 = 10 વર્ષ.","વ્યક્તિની ઉંમર = 4×10 = 40 વર્ષ."],"formula":"વ્યક્તિ : મિત્ર = 4 : 1  |  કુલ 5 ભાગ = 50  |  વ્યક્તિ = 4×10 = 40","check":"ચકાસણી: વ્યક્તિ 40 અને મિત્ર 10; સરવાળો 50.","kind":"ratio"},"11":{"title":"સંબંધને ગુણોત્તરમાં ફેરવવો","steps":["રવીનાની ઉંમર R અને સીમાની ઉંમર S માનો.","પ્રશ્ન મુજબ 2R = 3S. બંને બાજુ 2S થી ભાગાકાર કરતાં R:S = 3:2 મળે છે.","ઉંમરનો કુલ સરવાળો 75 છે; ગુણોત્તરના કુલ ભાગ 3+2 = 5.","એક ભાગ = 75 ÷ 5 = 15 વર્ષ.","રવીનાની ઉંમર 3 ભાગ = 3×15 = 45 વર્ષ."],"formula":"2R=3S  →  R:S=3:2  →  5 ભાગ=75  →  R=45","check":"ચકાસણી: R=45, S=30; 2×45 = 3×30 = 90 અને કુલ 75.","kind":"ratio"},"12":{"title":"ભૂતકાળનો સરવાળો અને ગુણોત્તર","steps":["હાલ પિતા અને પુત્રની કુલ ઉંમર 50 વર્ષ છે.","પાંચ વર્ષ પહેલાં બંનેની ઉંમરમાંથી 5-5 વર્ષ ઘટે છે; એટલે તે સમયનો કુલ સરવાળો 50−10 = 40 વર્ષ.","પાંચ વર્ષ પહેલાં પિતા:પુત્ર = 4:1. કુલ 5 ભાગ = 40, એટલે એક ભાગ = 8.","પુત્રની પાંચ વર્ષ પહેલાંની ઉંમર 8 વર્ષ હતી.","હાલ પુત્ર = 8+5 = 13 વર્ષ. પ્રશ્ન પાંચ વર્ષ પછી પૂછે છે, એટલે 13+5 = 18 વર્ષ."],"formula":"હાલ કુલ 50  →  5 વર્ષ પહેલાં કુલ 40  →  પુત્ર 8  →  હાલ 13  →  5 વર્ષ પછી 18","check":"ચકાસણી: હાલ પિતા 37 અને પુત્ર 13; કુલ 50. પાંચ વર્ષ પહેલાં 32 અને 8, એટલે 4:1.","kind":"timeline"},"13":{"title":"ગુણોત્તર અને તફાવત","steps":["મોટા અને નાના વિદ્યાર્થીની ઉંમરનો ગુણોત્તર 12:11 છે.","ગુણોત્તરમાં તફાવત = 12−11 = 1 ભાગ.","વાસ્તવિક ઉંમરનો તફાવત 10 વર્ષ છે, એટલે 1 ભાગ = 10 વર્ષ.","નાના વિદ્યાર્થીના 11 ભાગ છે: 11×10 = 110 વર્ષ."],"formula":"મોટો 12 ભાગ | નાનો 11 ભાગ  →  તફાવત 1 ભાગ = 10  →  નાનો = 110","check":"ચકાસણી: ઉંમરો 120 અને 110; તફાવત 10 અને ગુણોત્તર 12:11.","kind":"ratio"},"14":{"title":"ગુણોત્તર અને તફાવત","steps":["મોટા:નાના વિદ્યાર્થીનો ગુણોત્તર 10:7 છે.","ભાગોનો તફાવત = 10−7 = 3 ભાગ.","આ 3 ભાગની કિંમત 9 વર્ષ છે, એટલે એક ભાગ = 9÷3 = 3 વર્ષ.","નાના વિદ્યાર્થીની ઉંમર = 7×3 = 21 વર્ષ."],"formula":"10 ભાગ − 7 ભાગ = 3 ભાગ = 9  →  1 ભાગ=3  →  નાનો=7×3=21","check":"ચકાસણી: મોટો 30 અને નાનો 21; તફાવત 9.","kind":"ratio"},"15":{"title":"ઉંમરનો સ્થિર તફાવત","steps":["પિતાની ઉંમર પુત્રી કરતાં 30 વર્ષ વધારે છે. આ તફાવત સમય બદલાય છતાં 30 જ રહેશે.","ત્રણ વર્ષ પછી પુત્રીની ઉંમર x અને પિતાની ઉંમર 7x થશે, કારણ કે પિતા સાત ગણા થશે.","ત્યારે બંનેનો તફાવત 7x−x = 6x છે.","6x = 30, એટલે x = 5. આ પુત્રીની ત્રણ વર્ષ પછીની ઉંમર છે.","પિતાની ત્રણ વર્ષ પછીની ઉંમર = 7×5 = 35. હાલની ઉંમર = 35−3 = 32 વર્ષ."],"formula":"તફાવત હંમેશાં 30  →  7x−x=30  →  x=5  →  પિતા (ભવિષ્ય)=35  →  હાલ=32","check":"ચકાસણી: હાલ પિતા 32 અને પુત્રી 2; 3 વર્ષ પછી 35 અને 5, એટલે 7:1.","kind":"timeline"},"16":{"title":"ઉંમરનો તફાવત અને ભૂતકાળનો ગુણોત્તર","steps":["ઇમરાન ન્યૂટન કરતાં 16 વર્ષ મોટો છે; એટલે દરેક સમયબિંદુએ તફાવત 16 જ રહેશે.","ચાર વર્ષ પહેલાં ઇમરાનની ઉંમર ન્યૂટનથી પાંચ ગણી હતી. એટલે તે સમયે ગુણોત્તર 5:1.","5 ભાગ અને 1 ભાગ વચ્ચેનો તફાવત 4 ભાગ છે. આ 4 ભાગ = 16 વર્ષ.","એક ભાગ = 16÷4 = 4 વર્ષ. ચાર વર્ષ પહેલાં ઇમરાન = 5×4 = 20 વર્ષ.","હાલની ઉંમર મેળવવા 4 ઉમેરો: 20+4 = 24 વર્ષ."],"formula":"4 ભાગનો તફાવત=16  →  1 ભાગ=4  →  ઇમરાન (4 વર્ષ પહેલાં)=20  →  હાલ=24","check":"ચકાસણી: ચાર વર્ષ પહેલાં ન્યૂટન 4 અને ઇમરાન 20; તફાવત 16 અને ગુણોત્તર 5:1.","kind":"ratio"},"17":{"title":"ઉંમરનો તફાવત અને ભૂતકાળનો ગુણોત્તર","steps":["અરૂણ અખિલ કરતાં 18 વર્ષ મોટો છે; આ તફાવત સ્થિર રહેશે.","આઠ વર્ષ પહેલાં અરૂણ:અખિલ = 7:1. એટલે તે સમયે તફાવત 7−1 = 6 ભાગ.","6 ભાગ = 18 વર્ષ, તેથી એક ભાગ = 3 વર્ષ.","અખિલની આઠ વર્ષ પહેલાંની ઉંમર 3 વર્ષ હતી.","હાલની ઉંમર = 3+8 = 11 વર્ષ."],"formula":"7 ભાગ − 1 ભાગ = 6 ભાગ = 18  →  1 ભાગ=3  →  અખિલ હાલ=3+8=11","check":"ચકાસણી: આઠ વર્ષ પહેલાં અખિલ 3 અને અરૂણ 21; તફાવત 18, અરૂણ સાત ગણો.","kind":"ratio"},"18":{"title":"ઉંમરનો તફાવત અને ભૂતકાળનો ગુણોત્તર","steps":["મોટી બહેન નાની બહેન કરતાં 10 વર્ષ મોટી છે; આ તફાવત હંમેશાં 10 રહેશે.","પાંચ વર્ષ પહેલાં મોટી:નાની = 2:1.","બે ભાગ અને એક ભાગ વચ્ચેનો તફાવત 1 ભાગ છે; આ 1 ભાગ = 10 વર્ષ.","નાની બહેન પાંચ વર્ષ પહેલાં 10 વર્ષની હતી અને મોટી 20 વર્ષની હતી.","હાલની મોટી બહેનની ઉંમર = 20+5 = 25 વર્ષ."],"formula":"5 વર્ષ પહેલાં: નાની 10, મોટી 20  →  હાલ મોટી=20+5=25","check":"ચકાસણી: પાંચ વર્ષ પહેલાં 20:10 = 2:1 અને તફાવત 10.","kind":"timeline"},"19":{"title":"ઉંમરનો તફાવત અને ભૂતકાળનો ગુણોત્તર","steps":["P, Q કરતાં 21 વર્ષ મોટો છે; તફાવત 21 સ્થિર છે.","એક વર્ષ પહેલાં P:Q = 4:1. ગુણોત્તરમાં તફાવત 3 ભાગ છે.","3 ભાગ = 21, એટલે એક ભાગ = 7 વર્ષ.","એક વર્ષ પહેલાં P = 4×7 = 28 વર્ષ.","હાલ P = 28+1 = 29 વર્ષ."],"formula":"4−1=3 ભાગ=21  →  1 ભાગ=7  →  P (1 વર્ષ પહેલાં)=28  →  હાલ=29","check":"ચકાસણી: એક વર્ષ પહેલાં Q=7 અને P=28; તફાવત 21 તથા P ચાર ગણો.","kind":"ratio"},"20":{"title":"ઉંમરનો તફાવત અને ભવિષ્યનો ગુણોત્તર","steps":["A, B કરતાં 25 વર્ષ મોટો છે; એટલે A−B = 25 હંમેશાં.","પાંચ વર્ષ પછી Aની ઉંમર Bની બમણી થશે.","તે ભવિષ્યના સમયે B=x અને A=2x માનો. તફાવત 2x−x=x છે.","x=25 એટલે પાંચ વર્ષ પછી A=50 વર્ષ.","હાલની Aની ઉંમર = 50−5 = 45 વર્ષ."],"formula":"5 વર્ષ પછી: B=25, A=50  →  હાલ A=50−5=45","check":"ચકાસણી: હાલ A=45, B=20; તફાવત 25. પાંચ વર્ષ પછી 50 અને 25 એટલે બમણું.","kind":"timeline"},"21":{"title":"ઉંમરનો તફાવત અને ભૂતકાળનો ગુણોત્તર","steps":["મોટી અને નાની વ્યક્તિ વચ્ચેનો તફાવત 30 વર્ષ છે.","ત્રણ વર્ષ પહેલાં મોટી વ્યક્તિ નાનીથી છ ગણી હતી; ગુણોત્તર 6:1.","ભાગોનો તફાવત 6−1 = 5 ભાગ = 30 વર્ષ, એટલે એક ભાગ = 6 વર્ષ.","ત્રણ વર્ષ પહેલાં નાની વ્યક્તિ 6 અને મોટી 36 વર્ષની હતી.","હાલની ઉંમરો મેળવવા 3 ઉમેરો: નાની 9 અને મોટી 39 વર્ષ."],"formula":"3 વર્ષ પહેલાં: નાની 6 | મોટી 36  →  હાલ: 9 | 39","check":"ચકાસણી: ત્રણ વર્ષ પહેલાં 36:6 = 6:1 અને તફાવત 30.","kind":"timeline"},"22":{"title":"ઉંમરનો તફાવત અને ભૂતકાળનો ગુણોત્તર","steps":["બંને વ્યક્તિઓનો હાલનો તફાવત 24 વર્ષ છે.","દસ વર્ષ પહેલાં મોટી:નાની = 5:1.","ભાગોનો તફાવત 5−1 = 4 ભાગ = 24, એટલે એક ભાગ = 6 વર્ષ.","દસ વર્ષ પહેલાં નાની 6 અને મોટી 30 વર્ષની હતી.","હાલની ઉંમર: નાની 6+10 = 16 અને મોટી 30+10 = 40 વર્ષ."],"formula":"10 વર્ષ પહેલાં: 6 અને 30  →  હાલ: 16 અને 40","check":"ચકાસણી: હાલ તફાવત 24; દસ વર્ષ પહેલાં 30:6 = 5:1.","kind":"timeline"},"23":{"title":"હાલના ગુણોત્તરથી ભૂતકાળનો ગુણોત્તર","steps":["આમી:માતા = 8:11 અને ઉંમરનો તફાવત 21 વર્ષ.","ભાગોનો તફાવત = 11−8 = 3 ભાગ = 21, એટલે એક ભાગ = 7 વર્ષ.","આમીની હાલની ઉંમર = 8×7 = 56; માતાની = 11×7 = 77 વર્ષ.","10 વર્ષ પહેલાં આમી 56−10 = 46 અને માતા 77−10 = 67 વર્ષની હતી.","ભૂતકાળનો ગુણોત્તર = 46:67. આ સંખ્યા વધુ સરળ પ્રમાણમાં ઘટતી નથી."],"formula":"હાલ: 56:77  →  10 વર્ષ પહેલાં: 46:67","check":"ચકાસણી: હાલનો તફાવત 77−56=21 અને ગુણોત્તર 8:11.","kind":"timeline"},"24":{"title":"હાલનો ગુણોત્તર અને ભવિષ્યનો ગુણોત્તર","steps":["મોહિત:સુનીલ = 12:17. તફાવત = 17−12 = 5 ભાગ.","વાસ્તવિક તફાવત 20 વર્ષ છે, એટલે એક ભાગ = 20÷5 = 4 વર્ષ.","મોહિત = 12×4 = 48 અને સુનીલ = 17×4 = 68 વર્ષ.","18 વર્ષ પછી ઉંમરો 66 અને 86 થશે.","નવો ગુણોત્તર 66:86 છે. બંનેને 2થી ભાગતાં 33:43 મળે છે."],"formula":"હાલ: 48:68  →  18 વર્ષ પછી: 66:86  →  33:43","check":"ચકાસણી: હાલનો તફાવત 20; 18 વર્ષ પછી પણ 86−66=20.","kind":"timeline"},"25":{"title":"હાલનો ગુણોત્તર અને ભવિષ્યનો ગુણોત્તર","steps":["મોહિત:સુનીલ = 9:17; ભાગોનો તફાવત 8 છે.","વાસ્તવિક તફાવત 32 વર્ષ હોવાથી એક ભાગ = 32÷8 = 4 વર્ષ.","મોહિત = 9×4 = 36 અને સુનીલ = 17×4 = 68 વર્ષ.","11 વર્ષ પછી ઉંમરો 47 અને 79 થશે.","અંતિમ ગુણોત્તર = 47:79. બંને સંખ્યાનો સામાન્ય ભાગાકાર નથી."],"formula":"હાલ: 36:68  →  11 વર્ષ પછી: 47:79","check":"ચકાસણી: 79−47 = 32; ઉંમરનો તફાવત યથાવત્.","kind":"timeline"},"26":{"title":"હાલનો ગુણોત્તર અને ભવિષ્યનો ગુણોત્તર","steps":["રોહન:સોહન = 4:9; ભાગોનો તફાવત 5 છે.","વાસ્તવિક તફાવત 10 વર્ષ છે, એટલે એક ભાગ = 10÷5 = 2 વર્ષ.","રોહન = 4×2 = 8 અને સોહન = 9×2 = 18 વર્ષ.","12 વર્ષ પછી તેઓ 20 અને 30 વર્ષના થશે.","20:30 ને 10થી ભાગતાં સરળ ગુણોત્તર 2:3 મળે છે."],"formula":"હાલ: 8:18  →  12 વર્ષ પછી: 20:30  →  2:3","check":"ચકાસણી: હાલ તફાવત 10; ભવિષ્યમાં પણ 30−20=10.","kind":"timeline"},"27":{"title":"સરવાળો અને બમણો તફાવત","steps":["પિતાની ઉંમર F અને પુત્રની ઉંમર S માનો.","કુલ ઉંમર F+S = 74.","તેમના તફાવતનો બમણો 40 છે: 2(F−S)=40. તેથી F−S=20.","સરવાળો અને તફાવત બંને સમીકરણ ઉમેરો: 2F = 74+20 = 94.","F = 94÷2 = 47 વર્ષ."],"formula":"F+S=74  અને  F−S=20  →  2F=94  →  F=47","check":"ચકાસણી: પિતા 47, પુત્ર 27; સરવાળો 74 અને બમણો તફાવત 2×20=40.","kind":"equation"},"28":{"title":"સરવાળો અને તફાવત","steps":["પિતાની ઉંમર F અને પુત્રની S માનો.","સરવાળો F+S = 62.","પ્રશ્નમાં ઉંમરના તફાવતનો બમણો 40 છે, એટલે F−S = 20.","બંને સમીકરણ ઉમેરો: (F+S)+(F−S)=62+20.","2F=82, તેથી પિતાની ઉંમર F=41 વર્ષ."],"formula":"F+S=62  અને  F−S=20  →  2F=82  →  F=41","check":"ચકાસણી: પિતા 41, પુત્ર 21; કુલ 62 અને બમણો તફાવત 40.","kind":"equation"},"29":{"title":"સરેરાશ અને ગુણોત્તર","steps":["ત્રણ છોકરીઓની સરેરાશ ઉંમર 18 વર્ષ છે.","કુલ ઉંમર = સરેરાશ × વ્યક્તિઓની સંખ્યા = 18×3 = 54 વર્ષ.","ઉંમરોનો ગુણોત્તર 1:2:3 છે; કુલ ભાગ = 1+2+3 = 6.","એક ભાગ = 54÷6 = 9 વર્ષ.","સૌથી નાની છોકરી 1 ભાગની છે, એટલે તેની ઉંમર 9 વર્ષ."],"formula":"સરેરાશ 18 × 3 = કુલ 54  →  1:2:3 = 6 ભાગ  →  નાની=9","check":"ચકાસણી: ઉંમરો 9, 18, 27; કુલ 54 અને સરેરાશ 54÷3=18.","kind":"ratio"},"30":{"title":"સરેરાશમાં ફેરફાર","steps":["સમિતિમાં કુલ 7 સભ્યો છે.","જૂના સભ્યના સ્થાને નવો સભ્ય આવ્યો અને સરેરાશ ઉંમર 3 વર્ષ ઘટી.","સરેરાશમાં 3 વર્ષનો ઘટાડો એટલે કુલ ઉંમરમાં 7×3 = 21 વર્ષનો ઘટાડો.","બાકીના 6 સભ્યો બદલાયા નથી; તેથી કુલ ઘટાડો માત્ર જૂના અને નવા સભ્યની ઉંમરના તફાવતને કારણે છે.","નવો સભ્ય જૂના સભ્ય કરતાં 21 વર્ષ નાનો છે."],"formula":"કુલ ઉંમરનો ઘટાડો = સભ્યો 7 × સરેરાશ ઘટાડો 3 = 21 વર્ષ","check":"ચકાસણી: 7 સભ્યોની સરેરાશ 3 ઘટે તો કુલ 21 વર્ષ ઘટે; આ જ બદલાયેલા સભ્યનો તફાવત છે.","kind":"equation"},"31":{"title":"બે અલગ સમયની સરેરાશ","steps":["ત્રણ વર્ષ પહેલાં પતિ, પત્ની અને બાળકની સરેરાશ 28 હતી. તે સમયે કુલ ઉંમર = 28×3 = 84.","ત્રણેયની હાલની કુલ ઉંમર માટે 3 વર્ષ દરેકને ઉમેરો: 84 + 3×3 = 93.","પાંચ વર્ષ પહેલાં પત્ની અને બાળકની સરેરાશ 18 હતી. તે સમયે તેમનો કુલ સરવાળો = 18×2 = 36.","હાલ સુધી પાંચ વર્ષમાં બે વ્યક્તિઓની ઉંમર કુલ 5+5 = 10 વર્ષ વધે છે. હાલનો પત્ની+બાળક સરવાળો = 36+10 = 46.","પતિની હાલની ઉંમર = ત્રણેયનો હાલનો સરવાળો 93 − પત્ની+બાળક 46 = 47 વર્ષ."],"formula":"ત્રણેય હાલ કુલ 84+9=93  |  પત્ની+બાળક હાલ 36+10=46  |  પતિ=93−46=47","check":"ચકાસણી: હાલ પતિ 47; પત્ની+બાળકનો સરવાળો 46; કુલ 93. ત્રણ વર્ષ પહેલાં કુલ 84 અને સરેરાશ 28.","kind":"timeline"},"32":{"title":"હાલનો ગુણોત્તર અને ભૂતકાળનો ગુણોત્તર","steps":["દીકરીની હાલની ઉંમર D માનો. માતાની ઉંમર ત્રણ ગણી હોવાથી S=3D.","નવ વર્ષ પહેલાં માતા 3D−9 અને દીકરી D−9 વર્ષની હતી.","તે સમયે માતા દીકરીથી છ ગણી હતી: 3D−9 = 6(D−9).","કૌંસ ખોલો: 3D−9 = 6D−54.","45 = 3D, એટલે D=15 વર્ષ."],"formula":"3D−9 = 6(D−9)  →  3D−9=6D−54  →  D=15","check":"ચકાસણી: હાલ દીકરી 15 અને માતા 45. નવ વર્ષ પહેલાં 6 અને 36; 36 = 6×6.","kind":"equation"},"33":{"title":"હાલ અને ભવિષ્યનો ગુણોત્તર","steps":["પુત્રની હાલની ઉંમર S માનો. પિતા પાંચ ગણા હોવાથી F=5S.","પાંચ વર્ષ પછી પિતા 5S+5 અને પુત્ર S+5 વર્ષનો થશે.","તે સમયે પિતા પુત્રથી ચાર ગણા: 5S+5 = 4(S+5).","કૌંસ ખોલો: 5S+5 = 4S+20.","S=15 વર્ષ. એટલે પુત્રની હાલની ઉંમર 15 વર્ષ."],"formula":"5S+5 = 4(S+5)  →  5S+5=4S+20  →  S=15","check":"ચકાસણી: હાલ પિતા 75 અને પુત્ર 15; પાંચ વર્ષ પછી 80 અને 20, એટલે 4:1.","kind":"equation"},"34":{"title":"બે ગુણોત્તરથી ઉંમર શોધવી","steps":["હાલ નીલમ:રજની = 8:3. એટલે હાલની ઉંમરો 8x અને 3x માનો.","ચાર વર્ષ પછી ગુણોત્તર 9:4 છે: (8x+4)/(3x+4)=9/4.","ક્રોસ ગુણાકાર: 4(8x+4)=9(3x+4).","32x+16=27x+36, એટલે 5x=20 અને x=4.","રજનીની હાલની ઉંમર = 3x = 12 વર્ષ."],"formula":"(8x+4)/(3x+4)=9/4  →  32x+16=27x+36  →  x=4  →  રજની=12","check":"ચકાસણી: હાલ 32 અને 12; ચાર વર્ષ પછી 36:16 = 9:4.","kind":"equation"},"35":{"title":"પ્રશ્નના આંકડામાં અસંગતતા","steps":["ઉંમરનો તફાવત સમય સાથે બદલાતો નથી. P, Q કરતાં 15 વર્ષ મોટો છે એમ માનીને Qની હાલની ઉંમર q લો.","પાંચ વર્ષ પહેલાં ગુણોત્તર 8:7 છે: (q+10)/(q−5)=8/7. ક્રોસ ગુણાકારથી 7q+70=8q−40, એટલે q=110.","હવે આજથી 10 વર્ષ પછી ગુણોત્તર 11:10 હોવું જોઈએ: (q+25)/(q+10)=11/10.","ક્રોસ ગુણાકારથી 10q+250=11q+110, એટલે q=140.","એક જ Qની હાલની ઉંમર પહેલી શરતથી 110 અને બીજી શરતથી 140 મળે છે. આ બંને એકસાથે સાચાં હોઈ શકતાં નથી.","અેથી પ્રશ્નના આપેલા ગુણોત્તર અને સમયગાળામાં અસંગતતા છે; કોઈ વિકલ્પને ગણિતથી સાચો સાબિત કરી શકાતો નથી."],"formula":"(પહેલી શરત) q=110  |  (બીજી શરત) q=140  →  અસંગતતા","check":"નોંધ: મૂળ answer keyમાં 40 વર્ષ દર્શાવાયું છે, પરંતુ 40 બંને શરતો સંતોષતું નથી. પ્રશ્નના સ્રોતમાં સુધારો જરૂરી છે.","kind":"warning"},"36":{"title":"હાલ અને ભવિષ્યનો ગુણોત્તર","steps":["પુત્રની હાલની ઉંમર S માનો; પિતા ત્રણ ગણા હોવાથી F=3S.","12 વર્ષ પછી પિતા 3S+12 અને પુત્ર S+12 થશે.","તે સમયે પિતા પુત્રથી બમણા: 3S+12 = 2(S+12).","કૌંસ ખોલો: 3S+12 = 2S+24.","S=12 વર્ષ. પિતાની હાલની ઉંમર = 3×12 = 36 વર્ષ."],"formula":"3S+12 = 2(S+12)  →  3S+12=2S+24  →  S=12  →  F=36","check":"ચકાસણી: હાલ પિતા 36, પુત્ર 12; 12 વર્ષ પછી 48 અને 24, એટલે બમણું.","kind":"equation"},"37":{"title":"બે ગુણોત્તર અને સમાન તફાવત","steps":["હાલ X:Y = 7:2, એટલે ઉંમરો 7x અને 2x.","હાલનો તફાવત = 5x.","ચાર વર્ષ પછી ગુણોત્તર 8:3; ઉંમરો 7x+4 અને 2x+4.","આ નવા ગુણોત્તરમાં તફાવત 8−3 = 5 ભાગ છે, એટલે તફાવત 5x જ રહે છે. બંને ગુણોત્તરના તફાવતના ભાગ સરખા છે; ક્રોસ ગુણાકારથી x=4 મળે છે.","Xની હાલની ઉંમર = 7×4 = 28 વર્ષ."],"formula":"(7x+4)/(2x+4)=8/3  →  21x+12=16x+32  →  x=4  →  X=28","check":"ચકાસણી: હાલ 28:8 = 7:2; ચાર વર્ષ પછી 32:12 = 8:3.","kind":"equation"},"38":{"title":"હાલ અને ભૂતકાળના ગુણોત્તર — મૂળ જવાબમાં ભૂલ","steps":["દાદાની હાલની ઉંમર G માનો. પ્રશ્ન મુજબ કિસની ઉંમર ત્રણ ગણી છે: K=3G.","પાંચ વર્ષ પહેલાં K−5 = 4(G−5), કારણ કે ત્યારે કિસ દાદાથી ચાર ગણી હતી.","K=3G મૂકો: 3G−5 = 4G−20.","15 = G, એટલે દાદાની હાલની ઉંમર 15 વર્ષ.","કિસની હાલની ઉંમર K=3×15 = 45 વર્ષ. પ્રશ્ન કિસની ઉંમર પૂછે છે, દાદાની નહીં."],"formula":"3G−5 = 4(G−5)  →  3G−5=4G−20  →  G=15  →  K=45","check":"સાચો જવાબ 45 વર્ષ (વિકલ્પ D) થાય છે. મૂળ ફાઇલમાં વિકલ્પ B એટલે 15 વર્ષ દર્શાવાયું છે, જે દાદાની ઉંમર છે; જવાબ-કી સુધારેલી છે.","kind":"warning"},"39":{"title":"હાલ અને ભવિષ્યના ગુણોત્તર — મૂળ ગણિતની ભૂલ","steps":["ભત્રીજીની હાલની ઉંમર N માનો. મહિલાની ઉંમર છ ગણી હોવાથી W=6N.","ચાર વર્ષ પછી મહિલાની ઉંમર 6N+4 અને ભત્રીજીની N+4 થશે.","તે સમયે મહિલા ચાર ગણી: 6N+4 = 4(N+4).","કૌંસ ખોલો: 6N+4 = 4N+16.","2N=12, એટલે N=6 વર્ષ. મૂળ સમજૂતીમાં અંતિમ ભાગાકારમાં ભૂલથી 3 લખાયું છે."],"formula":"6N+4 = 4(N+4)  →  6N+4=4N+16  →  2N=12  →  N=6","check":"સાચો જવાબ 6 વર્ષ (વિકલ્પ C) થાય છે. મૂળ ફાઇલમાં 3 વર્ષ દર્શાવાયું છે, પરંતુ સમીકરણથી 6 મળે છે; જવાબ-કી સુધારેલી છે.","kind":"warning"},"40":{"title":"હાલ અને ભૂતકાળના ગુણોત્તર","steps":["પુત્રીની હાલની ઉંમર D માનો; માતાની ઉંમર 3D છે.","દસ વર્ષ પહેલાં માતા 3D−10 અને પુત્રી D−10 વર્ષની હતી.","તે સમયે માતા પાંચ ગણી: 3D−10 = 5(D−10).","કૌંસ ખોલો: 3D−10 = 5D−50.","40=2D, એટલે D=20 વર્ષ."],"formula":"3D−10 = 5(D−10)  →  3D−10=5D−50  →  D=20","check":"ચકાસણી: હાલ માતા 60 અને પુત્રી 20; દસ વર્ષ પહેલાં 50 અને 10, એટલે 5:1.","kind":"equation"},"41":{"title":"બે સમયના ગુણોત્તર અને તફાવત","steps":["છ વર્ષ પહેલાં X:Y = 9:5; તે સમયે તફાવત 4 ભાગ.","આજથી બે વર્ષ પછી X:Y = 13:9; તે સમયે પણ તફાવત 4 ભાગ.","X અને Y વચ્ચેનો વાસ્તવિક તફાવત સ્થિર છે. બંને સ્થિતિમાં 4 ભાગ એક જ તફાવત દર્શાવે છે.","આ બંને સમયબિંદુ વચ્ચે 8 વર્ષનું અંતર છે. ગુણોત્તરના ભાગોની ગણતરીથી એક ભાગ 2 વર્ષ મળે છે; તેથી છ વર્ષ પહેલાં Y=5×2=10.","હાલ Y=10+6=16 વર્ષ."],"formula":"6 વર્ષ પહેલાં Y=10  →  હાલ Y=10+6=16  |  2 વર્ષ પછી Y=18","check":"ચકાસણી: છ વર્ષ પહેલાં X=18,Y=10; હાલ 24,16; બે વર્ષ પછી 26,18 = 13:9.","kind":"timeline"},"42":{"title":"હાલ અને ભવિષ્યના ગુણોત્તર","steps":["અનિતા:અનુભવ = 3:5; હાલની ઉંમરો 3x અને 5x માનો.","ચાર વર્ષ પછી ગુણોત્તર 5:7: (3x+4)/(5x+4)=5/7.","ક્રોસ ગુણાકાર: 7(3x+4)=5(5x+4).","21x+28=25x+20; એટલે 8=4x અને x=2.","અનિતાની હાલની ઉંમર = 3×2 = 6 વર્ષ."],"formula":"(3x+4)/(5x+4)=5/7  →  21x+28=25x+20  →  x=2  →  અનિતા=6","check":"ચકાસણી: હાલ 6:10 = 3:5; ચાર વર્ષ પછી 10:14 = 5:7.","kind":"equation"},"43":{"title":"હાલ અને ભવિષ્યના ગુણોત્તર","steps":["હાલ A:B = 8:3; એટલે A=8x અને B=3x.","છ વર્ષ પછી A=8x+6 અને B=3x+6; ગુણોત્તર 19:9.","સમીકરણ: (8x+6)/(3x+6)=19/9.","ક્રોસ ગુણાકાર: 9(8x+6)=19(3x+6). એટલે 72x+54=57x+114.","15x=60, એટલે x=4. Aની હાલની ઉંમર = 8×4 = 32 વર્ષ."],"formula":"(8x+6)/(3x+6)=19/9  →  72x+54=57x+114  →  x=4  →  A=32","check":"ચકાસણી: હાલ 32:12=8:3; છ વર્ષ પછી 38:18=19:9.","kind":"equation"},"44":{"title":"હાલ અને ભવિષ્યના ગુણોત્તર","steps":["હાલ X:Y = 1:10. એટલે X=x અને Y=10x.","બે વર્ષ પછી ગુણોત્તર 1:4: (x+2)/(10x+2)=1/4.","ક્રોસ ગુણાકાર: 4(x+2)=10x+2.","4x+8=10x+2; એટલે 6=6x અને x=1.","Xની હાલની ઉંમર 1 વર્ષ."],"formula":"(x+2)/(10x+2)=1/4  →  4x+8=10x+2  →  x=1","check":"ચકાસણી: હાલ 1:10; બે વર્ષ પછી 3:12 = 1:4.","kind":"equation"},"45":{"title":"બે સમયના ગુણોત્તર","steps":["છ વર્ષ પહેલાં આફતાબ:સંજય = 6:5; એટલે તે સમયે ઉંમરો 6x અને 5x.","ચાર વર્ષ પછી એટલે છ વર્ષ પહેલાંથી કુલ 10 વર્ષ આગળ: ઉંમરો 6x+10 અને 5x+10.","તે સમયે ગુણોત્તર 11:10: (6x+10)/(5x+10)=11/10.","ક્રોસ ગુણાકાર: 10(6x+10)=11(5x+10). એટલે 60x+100=55x+110.","5x=10, એટલે x=2. છ વર્ષ પહેલાં સંજય 5×2=10 વર્ષનો હતો; હાલ 10+6=16 વર્ષ."],"formula":"(6x+10)/(5x+10)=11/10  →  60x+100=55x+110  →  x=2  →  સંજય હાલ=16","check":"ચકાસણી: છ વર્ષ પહેલાં 12:10=6:5; હાલ 18 અને16; ચાર વર્ષ પછી 22:20=11:10.","kind":"timeline"},"46":{"title":"હાલ અને ભવિષ્યનો ગુણોત્તર","steps":["પુત્રની હાલની ઉંમર S માનો; પિતા પાંચ ગણા એટલે F=5S.","ચાર વર્ષ પછી F+4 = 4(S+4).","સમીકરણમાં F=5S મૂકો: 5S+4=4S+16.","S=12 વર્ષ. એટલે પુત્રની હાલની ઉંમર 12 વર્ષ."],"formula":"5S+4 = 4(S+4)  →  5S+4=4S+16  →  S=12","check":"ચકાસણી: હાલ પિતા 60 અને પુત્ર 12; ચાર વર્ષ પછી 64 અને 16, એટલે 4:1.","kind":"equation"},"47":{"title":"હાલ અને ભવિષ્યના ગુણોત્તર","steps":["હાલ P:Q = 7:3; ભાગોનો તફાવત 4.","આઠ વર્ષ પછી ગુણોત્તર 11:7; ભાગોનો તફાવત પણ 4.","વાસ્તવિક ઉંમરનો તફાવત બંને સમયબિંદુએ સરખો રહે છે. તેથી 4 ભાગની કિંમત 8 વર્ષ છે; એક ભાગ = 2.","Pની હાલની ઉંમર = 7×2 = 14 વર્ષ."],"formula":"હાલ: 7:3  |  8 વર્ષ પછી: 11:7  →  4 ભાગ = 8  →  1 ભાગ=2  →  P=14","check":"ચકાસણી: હાલ P=14,Q=6; આઠ વર્ષ પછી 22:14 = 11:7.","kind":"ratio"},"48":{"title":"હાલ અને ભવિષ્યના ગુણોત્તર — પગલાં સાથે","steps":["હાલ A:B = 6:5; એટલે A=6x અને B=5x માનો.","છ વર્ષ પછી ગુણોત્તર 8:7 થશે: (6x+6)/(5x+6)=8/7.","ક્રોસ ગુણાકાર કરો: 7(6x+6)=8(5x+6).","42x+42=40x+48. હવે સમાન પદો એક બાજુ: 2x=6, એટલે x=3.","Aની હાલની ઉંમર = 6x = 6×3 = 18 વર્ષ.","અહીં ગુણોત્તરના તફાવતના ભાગ સમાન દેખાય છે, પરંતુ બંને ગુણોત્તરમાં ભાગની વાસ્તવિક કિંમત સરખી છે એવું તરત માની શકાય નહીં; સમીકરણથી x કાઢવું વધુ સલામત છે."],"formula":"(6x+6)/(5x+6)=8/7  →  42x+42=40x+48  →  x=3  →  A=18","check":"ચકાસણી: હાલ A=18, B=15. છ વર્ષ પછી 24:21 = 8:7.","kind":"equation"},"49":{"title":"હાલ અને ભવિષ્યના ગુણોત્તર","steps":["હાલ P:Q = 1:12; એટલે P=x અને Q=12x.","પાંચ વર્ષ પછી ગુણોત્તર 1:7: (x+5)/(12x+5)=1/7.","ક્રોસ ગુણાકાર: 7(x+5)=12x+5.","7x+35=12x+5; એટલે 30=5x અને x=6.","Pની હાલની ઉંમર 6 વર્ષ."],"formula":"(x+5)/(12x+5)=1/7  →  7x+35=12x+5  →  x=6","check":"ચકાસણી: હાલ 6:72=1:12; પાંચ વર્ષ પછી 11:77=1:7.","kind":"equation"},"50":{"title":"હાલ અને ભવિષ્યનો ગુણોત્તર","steps":["અહેમદ:અનંત = 3:2; એટલે હાલની ઉંમરો 3x અને 2x.","ત્રણ વર્ષ પછી ગુણોત્તર 6:5: (3x+3)/(2x+3)=6/5.","ક્રોસ ગુણાકાર: 5(3x+3)=6(2x+3).","15x+15=12x+18; એટલે 3x=3 અને x=1.","અનંતની હાલની ઉંમર = 2x = 2 વર્ષ."],"formula":"(3x+3)/(2x+3)=6/5  →  15x+15=12x+18  →  x=1  →  અનંત=2","check":"ચકાસણી: હાલ 3:2; ત્રણ વર્ષ પછી 6:5.","kind":"equation"},"51":{"title":"બે સમયબિંદુના સમીકરણ — મૂળ જવાબમાં ભૂલ","steps":["પોલની હાલની ઉંમર P અને પુત્રની S માનો.","10 વર્ષ પહેલાં પોલ પુત્રથી ત્રણ ગણો: P−10 = 3(S−10). તેથી P−10=3S−30, એટલે P=3S−20.","હાલથી 10 વર્ષ પછી પોલ પુત્રથી બમણો: P+10 = 2(S+10). તેથી P=2S+10.","બંને P સરખાં કરો: 3S−20 = 2S+10, એટલે S=30.","P=2S+10 = 60+10 = 70 વર્ષ. પોલની હાલની ઉંમર 70 વર્ષ."],"formula":"P=3S−20  અને  P=2S+10  →  S=30  →  P=70","check":"સાચો જવાબ 70 વર્ષ (વિકલ્પ A) છે. મૂળ ફાઇલમાં 50 વર્ષ દર્શાવાયું છે, જે બંને સમયની શરતો સંતોષતું નથી; જવાબ-કી સુધારેલી છે.","kind":"warning"},"52":{"title":"હાલ અને ભવિષ્યનો ગુણોત્તર","steps":["હાલ G:H = 6:5; એટલે ઉંમરો 6x અને 5x.","આઠ વર્ષ પછી ગુણોત્તર 8:7: (6x+8)/(5x+8)=8/7.","ક્રોસ ગુણાકાર: 7(6x+8)=8(5x+8).","42x+56=40x+64; એટલે 2x=8 અને x=4.","હાલનો કુલ સરવાળો = 6x+5x = 11×4 = 44 વર્ષ."],"formula":"(6x+8)/(5x+8)=8/7  →  42x+56=40x+64  →  x=4  →  કુલ=44","check":"ચકાસણી: હાલ 24+20=44; આઠ વર્ષ પછી 32:28 = 8:7.","kind":"equation"},"53":{"title":"હાલનો ગુણોત્તર અને બે વિધાન","steps":["હાલની ઉંમરો 8x અને 9x માનો.","ચાર વર્ષ પછી (8x+4):(9x+4)=10:11.","ક્રોસ ગુણાકાર: 11(8x+4)=10(9x+4) → 88x+44=90x+40.","4=2x, એટલે x=2. હાલની ઉંમરો 16 અને 18 વર્ષ.","વિધાન I: 14 વર્ષ પછી 30:32 = 15:16. સાચું.","વિધાન II: 12 વર્ષ પછી 28:30 = 14:15. સાચું.","અેથી I અને II બંને સાચાં."],"formula":"હાલ 16:18  →  14 વર્ષ પછી 30:32=15:16  |  12 વર્ષ પછી 28:30=14:15","check":"બંને વિધાન અલગ-અલગ સમય માટે ચકાસ્યાં; બંને ગુણોત્તર ચોક્કસ મળે છે.","kind":"timeline"},"54":{"title":"હાલનો ગુણોત્તર અને બે વિધાન","steps":["હાલની ઉંમરો 12x અને 13x માનો.","ચાર વર્ષ પછી (12x+4):(13x+4)=14:15.","ક્રોસ ગુણાકાર: 15(12x+4)=14(13x+4).","180x+60=182x+56; એટલે 4=2x અને x=2.","હાલની ઉંમરો 24 અને 26 વર્ષ.","વિધાન I: 16 વર્ષ પછી 40:42 = 20:21; સાચું.","વિધાન II: 14 વર્ષ પછી 38:40 = 19:20; આપેલું 19:18 નથી, એટલે ખોટું.","અેથી માત્ર વિધાન I સાચું."],"formula":"હાલ 24:26  →  16 વર્ષ પછી 40:42=20:21  |  14 વર્ષ પછી 38:40=19:20","check":"વિધાન IIમાં આપેલો 19:18 ગુણોત્તર મળતો નથી. તેથી માત્ર I સાચું.","kind":"timeline"},"55":{"title":"હાલનો ગુણોત્તર અને બે વિધાન","steps":["હાલની ઉંમરો 10x અને 13x માનો.","છ વર્ષ પછી (10x+6):(13x+6)=23:29.","ક્રોસ ગુણાકાર: 29(10x+6)=23(13x+6).","290x+174=299x+138; એટલે 36=9x અને x=4.","હાલની ઉંમરો 40 અને 52 વર્ષ.","વિધાન I: 16 વર્ષ પછી 56:68 = 14:17; 14:15 નથી, એટલે ખોટું.","વિધાન II: 12 વર્ષ પછી 52:64 = 13:16; 13:15 નથી, એટલે ખોટું.","અેથી ન તો I કે ન તો II સાચું."],"formula":"હાલ 40:52  →  16 વર્ષ પછી 56:68=14:17  |  12 વર્ષ પછી 52:64=13:16","check":"બંને વિધાનમાં આપેલા ગુણોત્તર મળતા નથી; યોગ્ય વિકલ્પ 'ન તો I કે ન તો II'.","kind":"timeline"}};

